function createRegistry() {
  const adapters = new Map();
  const key = (name) => name.trim().toLowerCase();
  return {
    register(adapter) {
      const name = key(adapter.name);
      if (adapters.has(name)) throw new Error("already registered: " + name);
      adapters.set(name, adapter);
    },
    require(name) {
      const adapter = adapters.get(key(name));
      if (adapter === undefined) throw new Error("not registered: " + key(name));
      return adapter;
    },
  };
}

const registry = createRegistry();
registry.register({ name: "Fake-Payments" });
console.log(registry.require(" fake-payments ").name);
for (const attempt of [() => registry.register({ name: "FAKE-PAYMENTS" }), () => registry.require("kobopay")]) {
  try {
    attempt();
  } catch (error) {
    console.log(error.message);
  }
}

