const RANK = { healthy: 0, degraded: 1, unhealthy: 2 };

function combine(reports) {
  let worst = "healthy";
  for (const { status } of Object.values(reports)) {
    if ((RANK[status] ?? RANK.unhealthy) > RANK[worst]) worst = status in RANK ? status : "unhealthy";
  }
  return worst;
}

