async function disposeAll(adapters) {
  const failures = [];
  for (const adapter of adapters) {
    try {
      await adapter.stop?.();
    } catch (error) {
      failures.push(error);
    }
    try {
      await adapter.dispose?.();
    } catch (error) {
      failures.push(error);
    }
  }
  if (failures.length > 0) throw new AggregateError(failures, "One or more adapters failed to dispose.");
}

